/* Beruf-Zugriff und Fortschritts-Brücke (wird von mkaufg.py an aufgaben.js angehängt; Quelle: quelle/gen/berufreg.js, nicht in lochmaster-web bearbeiten).
   BerufReg.cur()        gewählter Beruf (egs, ige, im, tpd, fll, ik, fi oder einer der Wege tec, stu, wing, winf): ?beruf=… in der Adresse, sonst lm4.beruf, sonst egs
   BerufReg.labs(b)      Lab-Schlüssel dieses Berufs (ohne Hubs), Reihenfolge wie LAB_REG
   BerufReg.rows(b)      Aufgabenzeilen dieser Labs
   BerufReg.has(lab, b)  gehört das Lab zum Beruf?
   BerufReg.projects/others/projState/vbSummary/vbLab  Projekte nach Beruf (siehe unten, Quelle: window.VB_INDEX)
   Brücke: Die eigenständigen Labs (Präfix tol, zer, …) speichern ihren Stand unter lm4.<präfix>.prog / .hints / .ctipps.
   Die Brücke spiegelt ihn nach lm4.tdone (Prozent, Maximum), sim.hints und lm4.ctipps (Stufe, Maximum), damit Lernpfad, Karriere, Abzeichen,
   Dashboard, Coach, Duell und der Stand-Export die Labs wie alle anderen sehen. Gespiegelt wird beim Laden und bei jedem Schreiben der drei Schlüssel. */
(function (root) {
  var ALL = ['egs', 'ige', 'im', 'tpd', 'fll', 'ik', 'fi', 'tec', 'stu', 'wing', 'winf'];   // 7 Ausbildungsberufe, dann die 4 Wege Studium/Technik (tec, stu, wing, winf)
  var REG = root.LAB_REG || {}, ROWS = root.AUFGABEN || [];
  var ls = null; try { ls = root.localStorage; } catch (e) { ls = null; }
  function cur() {
    try { var q = /[?&]beruf=(\w+)/.exec(root.location.search); if (q && ALL.indexOf(q[1]) >= 0) return q[1]; } catch (e) {}
    try { var v = ls && ls.getItem('lm4.beruf'); if (v && ALL.indexOf(v) >= 0) return v; } catch (e) {}
    return 'egs';
  }
  function has(lab, b) { var r = REG[lab]; return !!r && !r.hub && (r.beruf || ['egs']).indexOf(b || cur()) >= 0; }
  function labs(b) { b = b || cur(); return Object.keys(REG).filter(function (k) { return has(k, b); }); }
  function rows(b) { var l = labs(b); return ROWS.filter(function (r) { return l.indexOf(r[1]) >= 0; }); }
  /* Projekte (Verbundprojekte): window.VB_INDEX kommt aus dem gleichen Lauf von mkaufg.py (Name, Symbol, Beruf, Stationen mit Lab-Aufgaben).
     projects(b)    Projekte dieses Berufs ('alle' passt zu jedem Beruf), sortiert nach order
     others(b)      die übrigen Projekte (andere Berufe)
     projState(id, b)  { started, done (bestandene Stationen), total (Stationen), fin (Gesamttest bestanden) } aus dem gespeicherten Projektstand; mit Beruf b zählen im berufsübergreifenden Projekt nur die Stationen dieses Berufs
     vbSummary(b)   { n, fertig, begonnen, list: [{ id, name, icon, n, done, fin, started }] } für die Projekt-Zeile der Startseite
     vbLab(lab, b)  Projekte, in denen das Lab vorkommt (als Arbeits-Lab einer Station oder über eine Lab-Aufgabe; im berufsübergreifenden Projekt nur Stationen deines Berufs): [{ id, name, st: [Stationsnummern], beruf }] */
  function vbList() { return Array.isArray(root.VB_INDEX) ? root.VB_INDEX.slice().sort(function (a, b) { return (a.order || 99) - (b.order || 99); }) : []; }
  var WEG = ['tec', 'stu', 'wing', 'winf'];   // Wege Studium/Technik: sehen alle Verbundprojekte mit allen Stationen und wählen die Rolle im Projekt (Toni 25.11.2026)
  function vbFits(p, b) { var x = p.beruf || ['egs']; b = b || cur(); return WEG.indexOf(b) >= 0 || x.indexOf('alle') >= 0 || x.indexOf(b) >= 0; }
  function jget(k) { try { var v = JSON.parse(ls && ls.getItem(k) || 'null'); return v && typeof v === 'object' ? v : null; } catch (e) { return null; } }
  /* Station gehört zu deinem Beruf? Nur im berufsübergreifenden Projekt ('alle') tragen Stationen eigene Berufe (s[4]); sonst zählen alle Stationen. */
  function vbOwn(p, s, b) { return !(p && (p.beruf || []).indexOf('alle') >= 0 && b && WEG.indexOf(b) < 0 && s[4] && s[4].length) || s[4].indexOf(b) >= 0; }
  function projState(id, b) {
    var p = vbList().filter(function (x) { return x.id === id; })[0], s = jget('verbund.' + id), st = jget('lm4.stats') || {}, done = 0, total = p ? p.st.length : 0;
    var own = p && b ? p.st.map(function (x) { return vbOwn(p, x, b) ? x[0] : null; }) : null;
    if (own) total = own.filter(Boolean).length;
    if (s && s.stations && typeof s.stations === 'object') Object.keys(s.stations).forEach(function (k) { var e = s.stations[k]; if (e && e.passed && !e.stale && (!own || own.indexOf(k) >= 0)) done++; });
    var fin = !!((s && s.final && s.final.ok) || (+st['vb' + id] >= 1));
    return { started: !!s, done: p ? Math.min(done, total) : done, total: total, fin: fin };
  }
  function vbSummary(b) {
    var l = vbList().filter(function (p) { return vbFits(p, b); }).map(function (p) { var s = projState(p.id, b); return { id: p.id, name: p.name, icon: p.icon, n: s.total, done: s.done, fin: s.fin, started: s.started || s.fin }; });
    return { n: l.length, fertig: l.filter(function (x) { return x.fin; }).length, begonnen: l.filter(function (x) { return x.started && !x.fin; }).length, list: l };
  }
  function vbLab(lab, b) {
    var out = [];
    vbList().forEach(function (p) {
      if (b && !vbFits(p, b)) return;
      var nr = [];
      p.st.forEach(function (s, i) { if (b && !vbOwn(p, s, b)) return; if (s[2] === lab || (s[3] || []).some(function (t) { return t[0] === lab; })) nr.push(i + 1); });
      if (nr.length) out.push({ id: p.id, name: p.name, st: nr, beruf: p.beruf });
    });
    return out;
  }
  root.BerufReg = { ALL: ALL, cur: cur, has: has, labs: labs, rows: rows,
    projects: function (b) { return vbList().filter(function (p) { return vbFits(p, b); }); },
    others: function (b) { return vbList().filter(function (p) { return !vbFits(p, b); }); },
    projState: projState, vbSummary: vbSummary, vbLab: vbLab };

  if (!ls) return;
  var PF = Object.keys(REG).filter(function (k) { return REG[k].eig; });   // eigenständige Labs (Präfix = Schlüssel)
  var DONEONLY = ['emb'].filter(function (p) { return PF.indexOf(p) >= 0; });   // Embedded vertieft speichert nur lm4.emb.done ({id:true}), kein prog: true zählt als 100 Prozent
  var OBJPROG = ['rg2'].filter(function (p) { return PF.indexOf(p) >= 0; });   // Regelungstechnik Aufbau speichert lm4.rg2.prog als { id: { ok, n, tip, sol } } (kein Prozentwert): ok zählt als 100 Prozent, tip ist die Tipp-Stufe
  var KEYRE = new RegExp('^lm4\\.(' + PF.join('|') + ')\\.(prog|hints|ctipps)$' + (DONEONLY.length ? '|^lm4\\.(' + DONEONLY.join('|') + ')\\.(done|tipps)$' : ''));
  function rd(k) { try { var v = JSON.parse(ls.getItem(k) || 'null'); return v && typeof v === 'object' && !Array.isArray(v) ? v : {}; } catch (e) { return {}; } }
  function mergeMax(dst, src) { var ch = false; Object.keys(src).forEach(function (id) { var v = +src[id]; if (isFinite(v) && v > (+dst[id] || 0)) { dst[id] = v; ch = true; } }); return ch; }
  function sync() {
    var td = rd('lm4.tdone'), hi = rd('sim.hints'), ct = rd('lm4.ctipps'), c1 = false, c2 = false, c3 = false;
    PF.forEach(function (p) {
      if (mergeMax(td, rd('lm4.' + p + '.prog'))) c1 = true;
      if (DONEONLY.indexOf(p) >= 0) { var dn = rd('lm4.' + p + '.done'), pc = {}; var mine = {}; ROWS.forEach(function (r) { if (r[1] === p) mine[r[0]] = 1; }); Object.keys(dn).forEach(function (id) { if (dn[id] && mine[id]) pc[id] = 100; }); if (mergeMax(td, pc)) c1 = true; var tp = rd('lm4.' + p + '.tipps'), th = {}; Object.keys(tp).forEach(function (id) { if (mine[id]) th[id] = tp[id]; }); if (mergeMax(hi, th)) c2 = true; }   // nur Ids, die dem Lab im Verzeichnis gehören; tipps = benutzte Tipp-Stufen
      if (OBJPROG.indexOf(p) >= 0) { var op = rd('lm4.' + p + '.prog'), oc = {}, oh = {}, om = {}; ROWS.forEach(function (r) { if (r[1] === p) om[r[0]] = 1; }); Object.keys(op).forEach(function (id) { var e = op[id]; if (!om[id] || !e || typeof e !== 'object') return; if (e.ok === true) oc[id] = 100; if (+e.tip > 0) oh[id] = Math.min(3, +e.tip); }); if (mergeMax(td, oc)) c1 = true; if (mergeMax(hi, oh)) c2 = true; }
      if (mergeMax(hi, rd('lm4.' + p + '.hints'))) c2 = true;
      if (mergeMax(ct, rd('lm4.' + p + '.ctipps'))) c3 = true;
    });
    try { if (c1) ls.setItem('lm4.tdone', JSON.stringify(td)); if (c2) ls.setItem('sim.hints', JSON.stringify(hi)); if (c3) ls.setItem('lm4.ctipps', JSON.stringify(ct)); } catch (e) {}
  }
  root.BerufReg.sync = sync;
  try {
    var P = root.Storage && root.Storage.prototype, orig = P && P.setItem;
    if (orig && !orig.__bruecke) {
      var wrap = function (k, v) { var r = orig.apply(this, arguments); try { if (this === ls && KEYRE.test(String(k))) sync(); } catch (e) {} return r; };
      wrap.__bruecke = true; P.setItem = wrap;
    }
  } catch (e) {}
  sync();
})(typeof window !== 'undefined' ? window : globalThis);
